    'input': input,
    'output': output,
    'cacheRead': cacheRead,
    'cacheWrite': cacheWrite,
    'total': total,
  };

  /// Deserializes from a JSON map produced by [toJson].
  factory UsageCost.fromJson(Map<String, dynamic> json) => UsageCost(
    input: (json['input'] as num? ?? 0).toDouble(),
