        expect(s1024.reserveTokens, 256);
        expect(s1024.keepRecentTokens, 512);

        final s512 = CompactionSettings.forWindow(512);
        expect(s512.reserveTokens, 128);
        expect(s512.keepRecentTokens, 256);
      },
    );

