  TaskAgentDefinition _resolveDefinition(String agentName) {
    final definition = registry.resolve(agentName);
    if (definition == null) {
      throw StateError(
        'Unknown agent type "$agentName" — available: '
        '${registry.agents.map((a) => a.name).join(', ')}',
