    this.defaultBackground = false,
    AgentOutputStore? outputs,
    TaskJobManager? jobManager,
    this.subagentManager,
    this.childSessionFactory,
    this.childSessionOpener,
    this.a2aManager,
    this.compactionEngine,
    this.misuseBreaker = true,
