  /// switch) reaches children — see [TaskToolConfig.streamFunction].
  TaskExecutor({
    required this.childTools,
    required this.streamFunction,
    required this.model,
    required this.registry,
    required this.semaphore,
    required this.store,
    this.rolesResolver,
