  final match = RegExp(r'\(empty\s*=\s*(.+?)\)').firstMatch(question);
  if (match != null) return match.group(1)!.trim();
  final keeps = RegExp(r"\(empty\s*keeps\s*'(.+?)'\)").firstMatch(question);
  if (keeps != null) return keeps.group(1)!.trim();
  return null;
}

