      const TaskAgentDefinition(
        name: 'worker',
        description: 'tiny worker',
        systemPrompt: 'w',
      ),
      const TaskAgentDefinition(
        name: 'minismol',
        description: 'worker on the smol role',
        systemPrompt: 'w',
        modelRole: smolModelRole,
