Design recap for `context_pressure.dart`:

```dart
/// Observed context pressure (gh-1742): the provider-reported truth layer
/// under the compaction trigger, the over-window guard and the ctx meter.
library;

import 'compaction.dart' show CompactionSettings, shouldCompact;
import '../types.dart' show Message, AssistantMessage, StopReason, Usage;

/// The context size a completed request was accepted at (gh-1742
/// invariant 1): `usage.input + usage.cacheRead` — what the provider
/// counted of the LAST request. Output/cache-write tokens are the
/// RESPONSE, not the context; totalTokens mixes both and over-counts.
int observedContextTokens(Usage usage) => usage.input + usage.cacheRead;

Usage? _validUsage(Message message) {
 if (message case AssistantMessage(:final stopReason, :final usage)) {
   if (stopReason != StopReason.aborted &&
       stopReason != StopReason.error &&
       observedContextTokens(usage) > 0) {
     return usage;
   }
 }
 return null;
}

/// The last provider-reported context size in [messages] — the most
/// recent assistant message whose usage reports a positive context, or
/// `null` when none does (fresh session, or a gateway that reports no
/// usage — E1: the caller degrades to estimate-only).
int? lastObservedContextTokens(List<Message> messages) {
 for (var i = messages.length - 1; i >= 0; i--) {
   final usage = _validUsage(messages[i]);
   if (usage != null) return observedContextTokens(usage);
 }
 return null;
}

/// Whether ANY assistant message in [messages] carries a usable
/// observation (E1: distinguishes "no observation YET" from "this
/// provider never reports usage").
bool hasAnyReportedUsage(List<Message> messages) =>
   messages.any((m) => _validUsage(m) != null);

/// Kalman-lite reconciliation (gh-1742 invariant 1): the pressure input is
/// the WORSE of the two channels — `max(estimate, observed)`. ...
int reconcileContextTokens({required int estimatedTokens, int? observedTokens}) {
 final observed = observedTokens;
 if (observed == null || observed <= 0) return estimatedTokens;
 return max(estimatedTokens, observed);
}

/// The pressure verdict at one turn boundary...
final class ContextPressureDecision {
 const ContextPressureDecision({required this.pressureTokens, required this.estimateTriggered, required this.observedTriggered});
 final int pressureTokens;
 final bool estimateTriggered;
 final bool observedTriggered;
 bool get triggered => estimateTriggered || observedTriggered;
 /// AC5: the observed channel fired while the estimate channel did not —
 /// the pass must run with `force: true` (the compactor's own
 /// shouldCompact re-check on the estimate basis would skip it).
 bool get needsForce => observedTriggered;
}

ContextPressureDecision assessContextPressure({
 required int estimatedTokens,
 int? observedTokens,
 required int contextWindow,
 required CompactionSettings settings,
}) {
 final pressure = reconcileContextTokens(estimatedTokens: estimatedTokens, observedTokens: observedTokens);
 final estimateTriggered = shouldCompact(pressure, contextWindow, settings);
 final headroom = contextWindow - settings.reserveTokens;
 final observedTriggered =
     observedTokens != null &&
     observedTokens > 0 &&
     observedTokens > headroom; // hmm — observedTriggered ⊆ estimateTriggered
