          reason: 'the observed-over-headroom channel must force the '
              'compaction pass',
        );
        // The child session gained a compaction record.
        final records = await wiring.sessionRecords('forced');
        expect(
          records.whereType<CompactionRecord>(),
          isNotEmpty,
