}) {
  final call = ToolCall(id: callId, name: 'read', arguments: const {});
  final partial = _assistant(
    content: [call],
    stopReason: StopReason.toolUse,
    input: input,
    cacheRead: cacheRead,
    totalTokens: totalTokens,
  );
