      if (decision.needsForce && (latch == null || observed > latch)) {
        _forcedObservedAt[id] = observed;
        runForced = true;
      } else if (!decision.observedTriggered &&
          (latch == null || observed < latch)) {
        _forcedObservedAt[id] = observed;
