      summary: fake.call,
      mainSummary: fake.call,
      smolModel: null,
      hooks: hooks,
      messageCap: 56,
    );

    final ok = await compactor.run();

    expect(ok, isTrue);
    expect(
      fake.calls,
      greaterThanOrEqualTo(1),
      reason:
          'the cap trigger fired the pass with tokens far under the '
          'token trigger',
    );
