      jobs: taskConfig.jobManager,
      readMessages: jsonlChildMessageReader(services.baseEnv),
      resumeChild: taskConfig.executor.resumeChild,
      executor: taskConfig.executor,
    ),
    taskTool(config: taskConfig),
  ];
