  }

  ToolCall backgroundSpawn(List<String> names) => ToolCall(
    id: 't1',
    name: 'task',
    arguments: {
      'context': 'ctx',
      'background': true,
      'tasks': [
        for (final name in names)
          {'name': name, 'agent': 'task', 'task': 'TASKMARK-$name do work'},
      ],
    },
  );

  test(
    'AC-A: idle parent wakes when a background child settles — async-result '
