library;

/// gh-1742 invariant 2 on the CLI host: the CLI owns the shared
/// per-model context-window registry, publishes `/model-edit` pins (and
/// endpoint detections) into it, and hands it to the `task` tool — a
/// child spawned AFTER a registry entry resolves the REGISTERED window,
/// not the one its wiring model still carries (the
/// 131,072-advertised-vs-478k-served asymmetry).
///
/// - AC2a: `/model-edit contextWindow <n>` publishes a user pin.
/// - AC2b: a later registry entry (a detection the model instance
///   missed) wins for children — the executor reads the registry before
///   the carried window.
import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

import 'agent_cli_test_support.dart';

/// The text carried by a transcript message.
String _messageText(Object message) {
  final content = switch (message) {
    UserMessage() => message.content,
    AssistantMessage() => message.content,
    ToolResultMessage() => message.content,
    _ => '',
  };
  return content is String
      ? content
      : content is List<ContentBlock>
      ? [
          for (final block in content)
            if (block is TextContent) block.text,
        ].join('\n')
      : '';
}

String _lastUserText(Context context) {
  for (final message in context.messages.reversed) {
    if (message is UserMessage) return _messageText(message);
  }
  return '';
}

/// The last assistant text of a scripted turn.
AssistantMessageEventStream _turn(String text) {
  final stream = AssistantMessageEventStream();
  final message = AssistantMessage(
    content: [TextContent(text: text)],
    api: testModel.api,
    provider: testModel.provider,
    model: testModel.id,
    usage: Usage.zero,
    stopReason: StopReason.stop,
    timestamp: DateTime.utc(2026),
  );
  stream
    ..push(StartEvent(partial: message))
    ..push(TextStartEvent(contentIndex: 0, partial: message))
    ..push(TextDeltaEvent(contentIndex: 0, delta: text, partial: message))
    ..push(DoneEvent(reason: StopReason.stop, message: message));
  stream.end();
  return stream;
}

/// A scripted stream: the parent replays [parentTurns] in order; a CHILD
/// run (its task carries the marker) replays a plain text turn.
final class _RegistryRouter {
  _RegistryRouter(this.parentTurns);

  final List<List<AssistantMessageEvent>> parentTurns;
  int _parentCalls = 0;

  AssistantMessageEventStream call(
    Model model,
    Context context, {
    CancelToken? cancelToken,
  }) {
    final text = _lastUserText(context);
    if (text.contains('KIDMARK')) return _turn('child done');
    final turns = parentTurns;
    final index = _parentCalls < turns.length ? _parentCalls : turns.length - 1;
    _parentCalls++;
    final events = turns[index];
    final stream = AssistantMessageEventStream();
    for (final event in events) {
      stream.push(event);
    }
    stream.end();
    return stream;
  }
}

AssistantMessageEvent _textEvent(String text) {
  final message = AssistantMessage(
    content: [TextContent(text: text)],
    api: testModel.api,
    provider: testModel.provider,
    model: testModel.id,
    usage: Usage.zero,
    stopReason: StopReason.stop,
    timestamp: DateTime.utc(2026),
  );
  return DoneEvent(reason: StopReason.stop, message: message);
}

void main() {
  late FakeCliIO io;

  setUp(() => io = FakeCliIO());
  tearDown(() => io.close());

  Future<AgentCli> bootedCli(StreamFunction stream) async {
    final cli = AgentCli(
      config: AgentCliConfig(
        model: testModel,
        apiKey: '[REDACTED:Sensitive Value]',
        env: MemoryExecutionEnv(
          cwd: '/work',
          shell: const UnavailableShell(),
        ),
        sessionRoot: '/sessions',
        approvalMode: ApprovalMode.yolo,
      ),
      io: io,
      streamFunction: stream,
    );
    final run = cli.run();
    io.sendLine('/help');
    await waitForIt(
      () => io.out.toString().contains('/tasks'),
      reason: 'REPL is up',
    );
    // The REPL future settles only at /exit; silence the dangling-run
    // checker by never awaiting it — tests end via tearDown.
    unawaited(run);
    return cli;
  }

