/// The last assistant text of a scripted turn.
AssistantMessageEventStream _turn(String text) {
  final stream = AssistantMessageEventStream();
  final message = AssistantMessage(
    content: [TextContent(text: text)],
    api: testModel.api,
    provider: testModel.provider,
    model: testModel.id,
    usage: Usage.zero,
    stopReason: StopReason.stop,
    timestamp: DateTime.utc(2026),
  );
  stream
    ..push(StartEvent(partial: message))
    ..push(TextStartEvent(contentIndex: 0, partial: message))
    ..push(TextDeltaEvent(contentIndex: 0, delta: text, partial: message))
    ..push(DoneEvent(reason: StopReason.stop, message: message));
  stream.end();
  return stream;
}

/// A scripted stream: the parent replays [parentTurns] in order; a CHILD
/// run (its task carries the marker) replays a plain text turn.
final class _RegistryRouter {
  _RegistryRouter(this.parentTurns);

  final List<List<AssistantMessageEvent>> parentTurns;
  int _parentCalls = 0;

  AssistantMessageEventStream call(
    Model model,
    Context context, {
    CancelToken? cancelToken,
  }) {
    final text = _lastUserText(context);
    if (text.contains('KIDMARK')) return _turn('child done');
    final turns = parentTurns;
    final index = _parentCalls < turns.length ? _parentCalls : turns.length - 1;
    _parentCalls++;
