    Model model,
    Context context, {
    CancelToken? cancelToken,
  }) {
    final turn = _isChildRun(context)
        ? textTurn('child done')
        : parentTurns[
            _parentCalls < parentTurns.length
                ? _parentCalls++
                : parentTurns.length - 1];
    return FakeStreamFunction([turn]).call(model, context);
  }
}

